import time
import math
import numpy as np
from scipy.optimize import linprog

EPS_IMP = 5e-10
EPS_SUM = 1e-12


def exact_c5(h):
    h = np.asarray(h, dtype=float).reshape(-1)
    n = h.size
    if n == 0 or not np.all(np.isfinite(h)):
        return float("inf")
    dx = 2.0 / float(n)
    vals = np.correlate(h, 1.0 - h, mode="full") * dx
    if vals.size == 0 or not np.all(np.isfinite(vals)):
        return float("inf")
    return float(np.max(vals))


def corr_values(h):
    h = np.asarray(h, dtype=float).reshape(-1)
    n = h.size
    if n == 0:
        return np.zeros(0)
    dx = 2.0 / float(n)
    return np.correlate(h, 1.0 - h, mode="full") * dx


def force_sum(h, S, tol=1e-13):
    h = np.asarray(h, dtype=float).reshape(-1).copy()
    n = h.size
    if n == 0:
        return h
    for _ in range(n + 50):
        r = float(S) - float(np.sum(h))
        if abs(r) <= tol:
            break
        if r > 0:
            idx = int(np.argmax(1.0 - h))
            d = min(r, 1.0 - h[idx])
            if d <= 0:
                break
            h[idx] += d
        else:
            idx = int(np.argmin(h))
            d = min(-r, h[idx])
            if d <= 0:
                break
            h[idx] -= d
    np.clip(h, 0.0, 1.0, out=h)
    for _ in range(500):
        r = float(S) - float(np.sum(h))
        if abs(r) <= 5e-15:
            break
        if r > 0:
            idxs = np.where(h < 1.0 - 1e-14)[0]
            if idxs.size == 0:
                break
            h[int(idxs[0])] += min(r, 1.0 - h[int(idxs[0])])
        else:
            idxs = np.where(h > 1e-14)[0]
            if idxs.size == 0:
                break
            h[int(idxs[0])] -= min(-r, h[int(idxs[0])])
    return h


def ensure_feasible(h):
    h = np.asarray(h, dtype=float).reshape(-1).copy()
    n = h.size
    if n == 0:
        return force_sum(np.array([0.5, 0.5]), 1.0)
    if not np.all(np.isfinite(h)):
        return force_sum(np.full(n, 0.5), 0.5 * n)
    np.clip(h, 0.0, 1.0, out=h)
    return force_sum(h, 0.5 * n)


def symmetrize(h):
    h = np.asarray(h, dtype=float).reshape(-1)
    n = h.size
    if n == 0:
        return h
    return ensure_feasible(0.5 * (h + h[::-1]))


def resample_h(h_old, n_new):
    h = np.asarray(h_old, dtype=float).reshape(-1)
    n_old = h.size
    n_new = int(max(2, n_new))
    if n_old == 0:
        return ensure_feasible(np.full(n_new, 0.5))
    if n_old == n_new:
        return ensure_feasible(h)
    x_old = (np.arange(n_old) + 0.5) * (2.0 / n_old)
    x_new = (np.arange(n_new) + 0.5) * (2.0 / n_new)
    y = np.interp(x_new, x_old, h, left=h[0], right=h[-1])
    return ensure_feasible(y)


def compute_grad_matrix(h):
    n = len(h)
    dx = 2.0 / n
    L = 2 * n - 1
    G = np.zeros((L, n))
    for m in range(L):
        k = m - n + 1
        if k >= 0:
            if n - k > 0:
                G[m, k:] += dx * (1.0 - h[:n - k])
                G[m, :n - k] -= dx * h[k:]
        else:
            kk = -k
            if n - kk > 0:
                G[m, :n - kk] += dx * (1.0 - h[kk:])
                G[m, kk:] -= dx * h[:n - kk]
    return G


def lp_minimax_step(h0, radius, margin=1e-10, max_radius_retry=3):
    n = len(h0)
    if n < 4:
        return None
    L = 2 * n - 1
    S = 0.5 * n
    c0 = corr_values(h0)
    G = compute_grad_matrix(h0)
    b_val = G @ h0 - c0
    b_ub = b_val + margin
    A_ub = np.hstack([G, -np.ones((L, 1))])
    c_obj = np.zeros(n + 1)
    c_obj[-1] = 1.0
    A_eq = np.zeros((1, n + 1))
    A_eq[0, :n] = 1.0
    b_eq = np.array([S])
    lb = np.maximum(0.0, h0 - radius)
    ub = np.minimum(1.0, h0 + radius)
    lb = np.minimum(lb, ub)
    bounds_h = list(zip(lb, ub))
    bounds_h.append((0.0, 1.0))
    for attempt in range(max_radius_retry + 1):
        r_cur = radius * (0.6 ** attempt) if attempt > 0 else radius
        lb2 = np.maximum(0.0, h0 - r_cur)
        ub2 = np.minimum(1.0, h0 + r_cur)
        lb2 = np.minimum(lb2, ub2)
        bounds2 = list(zip(lb2, ub2))
        bounds2.append((0.0, 1.0))
        try:
            res = linprog(c_obj, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                          bounds=bounds2, method='highs',
                          options={'time_limit': 30.0, 'presolve': True})
            if res.status == 0 and res.x is not None and np.all(np.isfinite(res.x)):
                return res.x[:n]
        except Exception:
            pass
    return None


def line_search(h0, h_lp, c0, alphas=None):
    if alphas is None:
        alphas = [1.0, 0.7, 0.4, 0.2, 0.1, 0.05, 0.02]
    h_lp = ensure_feasible(h_lp)
    delta = h_lp - h0
    best_h = None
    best_c = c0
    for a in alphas:
        h_try = h0 + a * delta
        h_try = ensure_feasible(h_try)
        c_try = exact_c5(h_try)
        if c_try < best_c - EPS_IMP:
            best_c = c_try
            best_h = h_try.copy()
            if a == 1.0:
                break
    return best_h, best_c


def local_lp_polish(h, c, stop_time, max_iter=150, r0=None, r_max=0.06, r_min=1e-5):
    n = len(h)
    h = ensure_feasible(h)
    c = exact_c5(h)
    if r0 is None:
        r0 = max(0.008, min(0.03, 12.0 / math.sqrt(max(n, 16))))
    r = r0
    fails = 0
    for it in range(max_iter):
        if time.monotonic() > stop_time:
            break
        h_lp = lp_minimax_step(h, r)
        if h_lp is None:
            fails += 1
            r = max(r_min, r * 0.5)
            if fails > 8:
                break
            continue
        h_new, c_new = line_search(h, h_lp, c)
        if h_new is not None:
            h = h_new
            c = c_new
            fails = 0
            if r < r_max:
                r = min(r_max, r * 1.3)
        else:
            fails += 1
            r = max(r_min, r * 0.45)
            if fails > 10 or r <= r_min * 1.5:
                break
    return h, c


def random_candidate(base, n, mode, rng):
    n = int(max(4, n))
    if base is not None:
        b = resample_h(base, n)
    else:
        b = np.full(n, 0.5)
    if mode == 0:
        scales = [0.003, 0.008, 0.015, 0.03, 0.06, 0.12]
        sc = scales[int(rng.integers(0, len(scales)))]
        h = b + rng.normal(0, sc, n)
    elif mode == 1:
        x = (np.arange(n) + 0.5) * (2.0 / n)
        k1 = int(rng.integers(1, 7))
        k2 = int(rng.integers(1, 11))
        a1 = float(rng.uniform(0.2, 0.45))
        a2 = float(rng.uniform(0.04, 0.2))
        p1 = float(rng.uniform(0, 2 * math.pi))
        p2 = float(rng.uniform(0, 2 * math.pi))
        h = 0.5 + a1 * np.sin(math.pi * k1 * x + p1) + a2 * np.sin(math.pi * k2 * x + p2)
        h = 0.5 * (h + b)
    elif mode == 2:
        nb = int(rng.integers(4, 12))
        nb = min(nb, n)
        cuts = np.sort(np.concatenate([[0.0], rng.uniform(0, 2, nb - 1), [2.0]]))
        vals = rng.uniform(0.1, 0.9, nb)
        x = (np.arange(n) + 0.5) * (2.0 / n)
        idx = np.clip(np.searchsorted(cuts, x, side='right') - 1, 0, nb - 1)
        h = vals[idx]
        h = 0.4 * h + 0.6 * b
    elif mode == 3:
        h = b + rng.normal(0, 0.02, n)
        thr = float(np.median(h))
        hi = float(rng.uniform(0.6, 0.9))
        lo = float(rng.uniform(0.1, 0.4))
        h = np.where(h > thr, hi, lo)
    else:
        h = (rng.random(n) < 0.5).astype(float)
    return ensure_feasible(h)


def get_parent():
    try:
        ph = globals().get("initial_h_values")
    except Exception:
        ph = None
    if ph is None:
        return None
    arr = np.asarray(ph, dtype=float).reshape(-1)
    if arr.size < 4 or not np.all(np.isfinite(arr)):
        return None
    return ensure_feasible(arr)


def try_update(h, c, n, best):
    if h is None or n <= 0 or not np.isfinite(c):
        return best
    bh, bc, bn = best
    if bh is None:
        return (h, c, n)
    if c < bc - EPS_IMP:
        return (h, c, n)
    if abs(c - bc) <= 1e-8 and n < bn:
        return (h, c, n)
    return best


def run(seed=42, budget_s=1100, **kwargs):
    seed = int(seed)
    try:
        budget = max(10.0, float(budget_s))
    except Exception:
        budget = 1100.0
    t0 = time.monotonic()
    t_end = t0 + budget
    reserve = 45.0
    deadline = t_end - reserve
    rng = np.random.default_rng(seed)

    best_h = None
    best_c = float("inf")
    best_n = 10 ** 9

    parent = get_parent()
    if parent is not None:
        c_p = exact_c5(parent)
        best_h, best_c, best_n = try_update(parent, c_p, len(parent), (best_h, best_c, best_n))
        h_sym = symmetrize(parent)
        c_sym = exact_c5(h_sym)
        best_h, best_c, best_n = try_update(h_sym, c_sym, len(h_sym), (best_h, best_c, best_n))
        h_flip = ensure_feasible(1.0 - parent)
        c_flip = exact_c5(h_flip)
        best_h, best_c, best_n = try_update(h_flip, c_flip, len(h_flip), (best_h, best_c, best_n))

    if best_h is None:
        best_h = ensure_feasible(np.full(64, 0.5))
        best_c = exact_c5(best_h)
        best_n = len(best_h)

    n_base = best_n

    # Phase 1: LP polish at parent dimension
    if time.monotonic() < deadline - 200:
        h1, c1 = local_lp_polish(best_h, best_c, deadline - 200, max_iter=120, r0=0.02, r_max=0.05)
        best_h, best_c, best_n = try_update(h1, c1, len(h1), (best_h, best_c, best_n))
        h_sym = symmetrize(h1)
        c_sym = exact_c5(h_sym)
        best_h, best_c, best_n = try_update(h_sym, c_sym, len(h_sym), (best_h, best_c, best_n))
        h_neg = ensure_feasible(1.0 - h1)
        c_neg = exact_c5(h_neg)
        best_h, best_c, best_n = try_update(h_neg, c_neg, len(h_neg), (best_h, best_c, best_n))

    # Phase 2: Multi-dimensional trial
    dims = sorted(set([n_base + d for d in [-6, -4, -3, -2, -1, 0, 1, 2, 3, 4, 6, 8, 12, 16, 20, 24]
                       if 24 <= n_base + d <= 100]))
    for nid in dims:
        if time.monotonic() > deadline - 120:
            break
        h_rep = resample_h(best_h, nid)
        c_rep = exact_c5(h_rep)
        best_h, best_c, best_n = try_update(h_rep, c_rep, nid, (best_h, best_c, best_n))
        if nid <= 80:
            h_pol, c_pol = local_lp_polish(h_rep, c_rep, deadline - 120, max_iter=60, r0=0.015, r_max=0.04)
            best_h, best_c, best_n = try_update(h_pol, c_pol, nid, (best_h, best_c, best_n))
            h_sym = symmetrize(h_pol)
            c_sym = exact_c5(h_sym)
            best_h, best_c, best_n = try_update(h_sym, c_sym, len(h_sym), (best_h, best_c, best_n))

    # Phase 3: Coarse-to-fine
    coarse_dims = [16, 20, 24, 28, 32, 36, 40, 44, 48]
    for nc in coarse_dims:
        if time.monotonic() > deadline - 100:
            break
        h_co = resample_h(best_h, nc)
        c_co = exact_c5(h_co)
        h_pol, c_pol = local_lp_polish(h_co, c_co, deadline - 100, max_iter=50, r0=0.025, r_max=0.08)
        if time.monotonic() > deadline - 60:
            continue
        h_fine = resample_h(h_pol, n_base)
        c_fine = exact_c5(h_fine)
        best_h, best_c, best_n = try_update(h_fine, c_fine, n_base, (best_h, best_c, best_n))
        if c_fine < best_c + 0.005:
            h_pol2, c_pol2 = local_lp_polish(h_fine, c_fine, deadline - 60, max_iter=40, r0=0.012, r_max=0.035)
            best_h, best_c, best_n = try_update(h_pol2, c_pol2, len(h_pol2), (best_h, best_c, best_n))

    # Phase 4: Random exploration with LP polish
    modes = [0, 0, 0, 1, 1, 2, 3, 4]
    dim_pool = [n_base + d for d in [-4, -2, -1, 0, 1, 2, 4, 6, 8] if 24 <= n_base + d <= 80]
    if not dim_pool:
        dim_pool = [n_base]
    attempts = 0
    while time.monotonic() < deadline - 80 and attempts < 80:
        if time.monotonic() > deadline - 85:
            break
        mode = modes[int(rng.integers(0, len(modes)))]
        ntry = dim_pool[int(rng.integers(0, len(dim_pool)))]
        if rng.random() < 0.65:
            base = best_h
        else:
            base = None
        h_r = random_candidate(base, ntry, mode, rng)
        c_r = exact_c5(h_r)
        best_h, best_c, best_n = try_update(h_r, c_r, ntry, (best_h, best_c, best_n))
        if c_r < best_c + 0.012 and time.monotonic() < deadline - 100:
            h_pol, c_pol = local_lp_polish(h_r, c_r, deadline - 100, max_iter=30, r0=0.012, r_max=0.035)
            best_h, best_c, best_n = try_update(h_pol, c_pol, len(h_pol), (best_h, best_c, best_n))
            h_sym = symmetrize(h_pol)
            c_sym = exact_c5(h_sym)
            best_h, best_c, best_n = try_update(h_sym, c_sym, len(h_sym), (best_h, best_c, best_n))
        attempts += 1

    # Phase 5: Active lag gradient descent
    if time.monotonic() < deadline - 80 and best_h is not None:
        h_cur = best_h.copy()
        c_cur = best_c
        n_cur = len(h_cur)
        for gd_it in range(40):
            if time.monotonic() > deadline - 80:
                break
            c_vec = corr_values(h_cur)
            m_active = int(np.argmax(c_vec))
            G = compute_grad_matrix(h_cur)
            g_active = G[m_active]
            step_sizes = [0.01, 0.005, 0.002, 0.001]
            improved = False
            for ss in step_sizes:
                h_try = h_cur - ss * g_active
                h_try = ensure_feasible(h_try)
                c_try = exact_c5(h_try)
                if c_try < c_cur - EPS_IMP:
                    h_cur = h_try
                    c_cur = c_try
                    improved = True
                    break
            if not improved:
                break
            best_h, best_c, best_n = try_update(h_cur, c_cur, n_cur, (best_h, best_c, best_n))

    # Phase 6: Final polish
    if best_h is not None and time.monotonic() < deadline - 30:
        h_final, c_final = local_lp_polish(best_h, best_c, deadline - 30, max_iter=80, r0=0.01, r_max=0.03)
        best_h, best_c, best_n = try_update(h_final, c_final, len(h_final), (best_h, best_c, best_n))
        h_sym = symmetrize(h_final)
        c_sym = exact_c5(h_sym)
        best_h, best_c, best_n = try_update(h_sym, c_sym, len(h_sym), (best_h, best_c, best_n))
        h_neg = ensure_feasible(1.0 - h_final)
        c_neg = exact_c5(h_neg)
        best_h, best_c, best_n = try_update(h_neg, c_neg, len(h_neg), (best_h, best_c, best_n))

    # Final verification
    if best_h is None:
        best_h = ensure_feasible(np.full(64, 0.5))
    h_ret = ensure_feasible(best_h)
    c_ret = exact_c5(h_ret)
    if not np.isfinite(c_ret):
        h_ret = ensure_feasible(np.full(64, 0.5))
        c_ret = exact_c5(h_ret)
    return h_ret, float(c_ret), int(h_ret.size)
